// Mission 002 — Explore the Coastal District.
//
// Unlike Mission 001 (classroom zones synced through the backend), Mission 002
// runs entirely on the client: the coastal world is generated by terrain.js and
// has no server-side zone list yet. Progress is kept in sessionStorage so a
// refresh does not lose it, and can be wired to the backend in a later phase.
//
// Zones are world-space rectangles on the ground plan. They deliberately do not
// overlap, so ZoneDetector can report exactly one of them at a time.

export const COASTAL_MISSION = Object.freeze({
  code: "002",
  title: "Explore the Coastal District",
  description:
    "Walk the shoreline, cross the river and find the fishing harbour before the next drill.",
  objective: "Explore the coastal environment",
  mode: "TRAINING",
});

// Where the player appears when Mission 002 starts: on the open ground between
// the beachfront hotels and the promenade, facing the sea.
export const COASTAL_SPAWN = Object.freeze({ x: 0, z: -238 });

